+type Version = [number, number, number];
+type Predicate = (version: Version) => boolean;
+
+/** A possibly partial version; `undefined` marks a missing or wildcard number. */
+interface PartialVersion {
+  major: number | undefined;
+  minor: number | undefined;
+  patch: number | undefined;
+}
+
+const FULL_VERSION = /^\d+\.\d+\.\d+$/;
+const PARTIAL_VERSION = /^(\d+|[xX*])(\.(\d+|[xX*])){0,2}$/;
+const COMPARATOR = /^(<=|>=|<|>|=|~|\^)?(.*)$/;
+
+function parseVersion(text: string): Version {
+  if (!FULL_VERSION.test(text)) {
+    throw new Error(`Invalid version: ${text}`);
+  }
+  return text.split(".").map(Number) as Version;
+}
+
+function parsePartial(text: string): PartialVersion {
+  if (!PARTIAL_VERSION.test(text)) {
+    throw new Error(`Invalid version: ${text}`);
+  }
+  const numbers: (number | undefined)[] = [];
+  let wildcard = false;
+  for (const part of text.split(".")) {
+    if (/^[xX*]$/.test(part)) {
+      wildcard = true;
+      numbers.push(undefined);
+    } else if (wildcard) {
+      throw new Error(`Invalid version: ${text}`);
+    } else {
+      numbers.push(Number(part));
+    }
+  }
+  return { major: numbers[0], minor: numbers[1], patch: numbers[2] };
+}
+
+function compare(a: Version, b: Version): number {
+  for (let i = 0; i < 3; i++) {
+    if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
+  }
+  return 0;
+}
